FROM (SELECT sscd.*, ROW_NUMBER() OVER (PARTITION BY main_id ORDER BY effective_date DESC, update_time DESC) AS rn FROM sku_std_cost_detail sscd WHERE sscd.is_deleted = false) sscd LEFT JOIN sku_std_cost as ssc on sscd.main_id = ssc.id LEFT JOIN product_detail as pd on pd.id = ssc.sku_id LEFT JOIN product_sale as ps on ps.sku_id = ssc.sku_id WHERE ${params.sqlMap.default} and ssc.is_deleted = false and pd.is_deleted = false and ps.is_deleted = false
